void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Clear and reuse the bucket with label minLabel from bucketsByLabel
    Set<Integer> oldBucket = bucketsByLabel.get(minLabel);
    if (oldBucket != null) {
        bucketsByLabel.remove(minLabel);
        bucketsByLabel.add(0, oldBucket);
    }

    // Update the labeling of the buckets
    for (int i = minLabel + 1; i < bucketsByLabel.size(); i++) {
        Set<Integer> currentBucket = bucketsByLabel.get(i);
        if (currentBucket != null) {
            Set<Integer> prevBucket = bucketsByLabel.get(i - 1);
            prevBucket.addAll(currentBucket);
            currentBucket.clear();
        }
    }
}

