public class SuffixSum {
    public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        List<Integer> suffixSum = new ArrayList<>();
        long sumAllElements = 0;

        for (int i = 1; i < bounds.size(); i++) {
            int current = bounds.get(i);
            suffixSum.add(suffixSum.isEmpty() ? 0 : suffixSum.get(suffixSum.size() - 1)) + current;
            sumAllElements += current;
        }

        suffixSum.add(sumAllElements);
        return new Pair<>(suffixSum, sumAllElements);
    }
}

